public final class ProductActivity extends Activity{private CoreDb db;@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_product);db=new CoreDb(this);Native4Services services=new Native4Services(db,"native4-android-alpha");new CoreProductPanelBinder(this,services,(TextView)findViewById(R.id.status));findViewById(R.id.pageBack).setOnClickListener(v->finish());Button audit=new Button(this);audit.setText("تدقيق المنتجات — قراءة فقط");audit.setOnClickListener(v->startActivity(new Intent(this,ProductAuditActivity.class)));android.view.ViewGroup root=findViewById(android.R.id.content);if(root.getChildCount()>0&&root.getChildAt(0) instanceof android.view.ViewGroup)((android.view.ViewGroup)root.getChildAt(0)).addView(audit,0);}}